CREATE SCHEMA IF NOT EXISTS omop;
CREATE OR REPLACE VIEW omop."omop_conceptmap" AS
SELECT
    CASE WHEN (array_length(fhirpath(group_elem_0, 'iif(source = ''http://loinc.org'', ''LOINC'', iif(source = ''http://snomed.info/sct'', ''SNOMED'', iif(source = ''http://www.nlm.nih.gov/research/umls/rxnorm'', ''RxNorm'', iif(source = ''http://hl7.org/fhir/sid/icd-10-cm'', ''ICD10CM'', iif(source = ''http://hl7.org/fhir/sid/icd-10'', ''ICD10'', iif(source = ''http://www.ama-assn.org/go/cpt'', ''CPT4'', iif(source = ''urn:oid:2.16.840.1.113883.6.14'', ''HCPCS'', iif(source = ''http://hl7.org/fhir/sid/ndc'', ''NDC'', source))))))))')) > 1) OR (array_length(list_filter(COALESCE(CAST(json_extract(TRY_CAST(fhirpath_json(group_elem_0, 'iif(source = ''http://loinc.org'', ''LOINC'', iif(source = ''http://snomed.info/sct'', ''SNOMED'', iif(source = ''http://www.nlm.nih.gov/research/umls/rxnorm'', ''RxNorm'', iif(source = ''http://hl7.org/fhir/sid/icd-10-cm'', ''ICD10CM'', iif(source = ''http://hl7.org/fhir/sid/icd-10'', ''ICD10'', iif(source = ''http://www.ama-assn.org/go/cpt'', ''CPT4'', iif(source = ''urn:oid:2.16.840.1.113883.6.14'', ''HCPCS'', iif(source = ''http://hl7.org/fhir/sid/ndc'', ''NDC'', source))))))))') AS JSON), '$[*]') AS JSON[]), []::JSON[]), _j -> NOT (json_type(_j) IN ('NULL', 'VARCHAR')))) > 0) THEN error('ViewDefinition column ''vocabulary_id'' path "iif(source = %loinc_uri, ''LOINC'', iif(source = %snomed_uri, ''SNOMED'', iif(source = %rxnorm_uri, ''RxNorm'', iif(source = %icd10cm_uri, ''ICD10CM'', iif(source = %icd10_uri, ''ICD10'', iif(source = %cpt4_uri, ''CPT4'', iif(source = %hcpcs_uri, ''HCPCS'', iif(source = %ndc_uri, ''NDC'', source))))))))" violates collection=false / declared type string') ELSE NULLIF(fhirpath_text(group_elem_0, 'iif(source = ''http://loinc.org'', ''LOINC'', iif(source = ''http://snomed.info/sct'', ''SNOMED'', iif(source = ''http://www.nlm.nih.gov/research/umls/rxnorm'', ''RxNorm'', iif(source = ''http://hl7.org/fhir/sid/icd-10-cm'', ''ICD10CM'', iif(source = ''http://hl7.org/fhir/sid/icd-10'', ''ICD10'', iif(source = ''http://www.ama-assn.org/go/cpt'', ''CPT4'', iif(source = ''urn:oid:2.16.840.1.113883.6.14'', ''HCPCS'', iif(source = ''http://hl7.org/fhir/sid/ndc'', ''NDC'', source))))))))'), '') END as "vocabulary_id",
    CASE WHEN (array_length(fhirpath(group_elem_0, 'source')) > 1) OR (array_length(list_filter(COALESCE(CAST(json_extract(TRY_CAST(fhirpath_json(group_elem_0, 'source') AS JSON), '$[*]') AS JSON[]), []::JSON[]), _j -> NOT (json_type(_j) IN ('NULL', 'VARCHAR')))) > 0) THEN error('ViewDefinition column ''source_system'' path ''source'' violates collection=false / declared type uri') ELSE NULLIF(fhirpath_text(group_elem_0, 'source'), '') END as "source_system",
    CASE WHEN (array_length(fhirpath(element_elem_1, 'code')) > 1) OR (array_length(list_filter(COALESCE(CAST(json_extract(TRY_CAST(fhirpath_json(element_elem_1, 'code') AS JSON), '$[*]') AS JSON[]), []::JSON[]), _j -> NOT (json_type(_j) IN ('NULL', 'VARCHAR')))) > 0) THEN error('ViewDefinition column ''concept_code'' path ''code'' violates collection=false / declared type string') ELSE NULLIF(fhirpath_text(element_elem_1, 'code'), '') END as "concept_code",
    CASE WHEN (array_length(fhirpath(first___elem_2, 'code')) > 1) OR (array_length(list_filter(COALESCE(CAST(json_extract(TRY_CAST(fhirpath_json(first___elem_2, 'code') AS JSON), '$[*]') AS JSON[]), []::JSON[]), _j -> NOT (json_type(_j) IN ('NULL', 'VARCHAR')))) > 0) THEN error('ViewDefinition column ''concept_id'' path ''code'' violates collection=false / declared type string') ELSE NULLIF(fhirpath_text(first___elem_2, 'code'), '') END as "concept_id",
    CASE WHEN (array_length(fhirpath(first___elem_2, 'display')) > 1) OR (array_length(list_filter(COALESCE(CAST(json_extract(TRY_CAST(fhirpath_json(first___elem_2, 'display') AS JSON), '$[*]') AS JSON[]), []::JSON[]), _j -> NOT (json_type(_j) IN ('NULL', 'VARCHAR')))) > 0) THEN error('ViewDefinition column ''concept_name'' path ''display'' violates collection=false / declared type string') ELSE NULLIF(fhirpath_text(first___elem_2, 'display'), '') END as "concept_name",
    CASE WHEN (array_length(fhirpath(first___elem_2, 'equivalence')) > 1) OR (array_length(list_filter(COALESCE(CAST(json_extract(TRY_CAST(fhirpath_json(first___elem_2, 'equivalence') AS JSON), '$[*]') AS JSON[]), []::JSON[]), _j -> NOT (json_type(_j) IN ('NULL', 'VARCHAR')))) > 0) THEN error('ViewDefinition column ''equivalence'' path ''equivalence'' violates collection=false / declared type code') ELSE NULLIF(fhirpath_text(first___elem_2, 'equivalence'), '') END as "equivalence"
FROM "__vd_src" t
CROSS JOIN LATERAL (
    SELECT json_extract(jarr, '$[' || CAST(idx AS VARCHAR) || ']') as group_elem_0, idx as group_elem_0__row_index
    FROM (VALUES (fhirpath(t.resource, 'group'), fhirpath_json(t.resource, 'group'))) v(arr, jarr)
    CROSS JOIN UNNEST(range(len(arr))) AS u(idx)
    ORDER BY idx
) as group_elem_0_table
CROSS JOIN LATERAL (
    SELECT json_extract(jarr, '$[' || CAST(idx AS VARCHAR) || ']') as element_elem_1, idx as element_elem_1__row_index
    FROM (VALUES (fhirpath(group_elem_0, 'element'), fhirpath_json(group_elem_0, 'element'))) v(arr, jarr)
    CROSS JOIN UNNEST(range(len(arr))) AS u(idx)
    ORDER BY idx
) as element_elem_1_table
CROSS JOIN LATERAL (
    SELECT json_extract(jarr, '$[' || CAST(idx AS VARCHAR) || ']') as first___elem_2, idx as first___elem_2__row_index
    FROM (VALUES (fhirpath(element_elem_1, 'target.where(equivalence = ''equivalent'' or equivalence = ''equal'' or equivalence = ''wider'' or equivalence = ''subsumes'').first()'), fhirpath_json(element_elem_1, 'target.where(equivalence = ''equivalent'' or equivalence = ''equal'' or equivalence = ''wider'' or equivalence = ''subsumes'').first()'))) v(arr, jarr)
    CROSS JOIN UNNEST(range(len(arr))) AS u(idx)
    ORDER BY idx
) as first___elem_2_table
WHERE json_extract_string(t.resource, '$.resourceType') = 'ConceptMap';
CREATE SCHEMA IF NOT EXISTS omop;
CREATE OR REPLACE VIEW omop."drug_exposure__medication_request" AS
SELECT
    CASE WHEN (array_length(fhirpath(t.resource, 'id')) > 1) OR (array_length(list_filter(fhirpath(t.resource, '(id).type().name'), _t -> NOT (_t IN ('id', 'string')))) > 0) THEN error('ViewDefinition column ''drug_exposure_id'' path ''id'' violates collection=false / declared type id') ELSE NULLIF(fhirpath_text(t.resource, 'id'), '') END as "drug_exposure_id",
    CASE WHEN (array_length(fhirpath(t.resource, 'subject.reference.split(''/'').last()')) > 1) OR ((array_length(fhirpath(t.resource, '(subject.reference.split(''/'').last()).type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(subject.reference.split(''/'').last()).type().name'), _t -> NOT (_t IN ('String', 'base64Binary', 'canonical', 'code', 'id', 'markdown', 'oid', 'string', 'uri', 'url', 'uuid')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, 'subject.reference.split(''/'').last()'), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(subject.reference.split(''/'').last()).type().name')) = 0)) THEN error('ViewDefinition column ''person_id'' path "subject.reference.split(''/'').last()" violates collection=false / declared type string') ELSE NULLIF(fhirpath_text(t.resource, 'subject.reference.split(''/'').last()'), '') END as "person_id",
    "cm"."concept_id" as "drug_concept_id",
    CASE WHEN (array_length(fhirpath(t.resource, 'authoredOn.substring(0, 10)')) > 1) OR ((array_length(fhirpath(t.resource, '(authoredOn.substring(0, 10)).type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(authoredOn.substring(0, 10)).type().name'), _t -> NOT (_t IN ('Date', 'DateTime', 'String', 'date', 'dateTime', 'string')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, 'authoredOn.substring(0, 10)'), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(authoredOn.substring(0, 10)).type().name')) = 0)) THEN error('ViewDefinition column ''drug_exposure_start_date'' path ''authoredOn.substring(0, 10)'' violates collection=false / declared type date') ELSE NULLIF(fhirpath_text(t.resource, 'authoredOn.substring(0, 10)'), '') END as "drug_exposure_start_date",
    CASE WHEN (array_length(fhirpath(t.resource, 'authoredOn')) > 1) OR (array_length(list_filter(fhirpath(t.resource, '(authoredOn).type().name'), _t -> NOT (_t IN ('Date', 'DateTime', 'String', 'date', 'dateTime', 'string')))) > 0) THEN error('ViewDefinition column ''drug_exposure_start_datetime'' path ''authoredOn'' violates collection=false / declared type dateTime') ELSE NULLIF(fhirpath_text(t.resource, 'authoredOn'), '') END as "drug_exposure_start_datetime",
    CASE WHEN (array_length(fhirpath(t.resource, 'iif(dosageInstruction.timing.boundsPeriod.end.exists(), dosageInstruction.timing.boundsPeriod.end.substring(0, 10), iif(dosageInstruction[0].asNeededBoolean.exists(), authoredOn.substring(0, 10), authoredOn.substring(0, 10)))')) > 1) OR ((array_length(fhirpath(t.resource, '(iif(dosageInstruction.timing.boundsPeriod.end.exists(), dosageInstruction.timing.boundsPeriod.end.substring(0, 10), iif(dosageInstruction[0].asNeededBoolean.exists(), authoredOn.substring(0, 10), authoredOn.substring(0, 10)))).type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(iif(dosageInstruction.timing.boundsPeriod.end.exists(), dosageInstruction.timing.boundsPeriod.end.substring(0, 10), iif(dosageInstruction[0].asNeededBoolean.exists(), authoredOn.substring(0, 10), authoredOn.substring(0, 10)))).type().name'), _t -> NOT (_t IN ('Date', 'DateTime', 'String', 'date', 'dateTime', 'string')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, 'iif(dosageInstruction.timing.boundsPeriod.end.exists(), dosageInstruction.timing.boundsPeriod.end.substring(0, 10), iif(dosageInstruction[0].asNeededBoolean.exists(), authoredOn.substring(0, 10), authoredOn.substring(0, 10)))'), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(iif(dosageInstruction.timing.boundsPeriod.end.exists(), dosageInstruction.timing.boundsPeriod.end.substring(0, 10), iif(dosageInstruction[0].asNeededBoolean.exists(), authoredOn.substring(0, 10), authoredOn.substring(0, 10)))).type().name')) = 0)) THEN error('ViewDefinition column ''drug_exposure_end_date'' path ''iif(dosageInstruction.timing.boundsPeriod.end.exists(), dosageInstruction.timing.boundsPeriod.end.substring(0, 10), iif(dosageInstruction[0].asNeededBoolean.exists(), authoredOn.substring(0, 10), authoredOn.substring(0, 10)))'' violates collection=false / declared type date') ELSE NULLIF(fhirpath_text(t.resource, 'iif(dosageInstruction.timing.boundsPeriod.end.exists(), dosageInstruction.timing.boundsPeriod.end.substring(0, 10), iif(dosageInstruction[0].asNeededBoolean.exists(), authoredOn.substring(0, 10), authoredOn.substring(0, 10)))'), '') END as "drug_exposure_end_date",
    CASE WHEN (array_length(fhirpath(t.resource, 'authoredOn')) > 1) OR (array_length(list_filter(fhirpath(t.resource, '(authoredOn).type().name'), _t -> NOT (_t IN ('Date', 'DateTime', 'String', 'date', 'dateTime', 'string')))) > 0) THEN error('ViewDefinition column ''drug_exposure_end_datetime'' path ''authoredOn'' violates collection=false / declared type dateTime') ELSE NULLIF(fhirpath_text(t.resource, 'authoredOn'), '') END as "drug_exposure_end_datetime",
    CASE WHEN (array_length(fhirpath(t.resource, '''38000177''')) > 1) OR ((array_length(fhirpath(t.resource, '(''38000177'').type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(''38000177'').type().name'), _t -> NOT (_t IN ('String', 'base64Binary', 'canonical', 'code', 'id', 'markdown', 'oid', 'string', 'uri', 'url', 'uuid')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, '''38000177'''), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(''38000177'').type().name')) = 0)) THEN error('ViewDefinition column ''drug_type_concept_id'' path ''%rx_prescription_written'' violates collection=false / declared type string') ELSE NULLIF(fhirpath_text(t.resource, '''38000177'''), '') END as "drug_type_concept_id",
    CASE WHEN (array_length(fhirpath(t.resource, 'dosageInstruction.text.first()')) > 1) OR ((array_length(fhirpath(t.resource, '(dosageInstruction.text.first()).type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(dosageInstruction.text.first()).type().name'), _t -> NOT (_t IN ('String', 'base64Binary', 'canonical', 'code', 'id', 'markdown', 'oid', 'string', 'uri', 'url', 'uuid')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, 'dosageInstruction.text.first()'), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(dosageInstruction.text.first()).type().name')) = 0)) THEN error('ViewDefinition column ''sig'' path ''dosageInstruction.text.first()'' violates collection=false / declared type string') ELSE NULLIF(fhirpath_text(t.resource, 'dosageInstruction.text.first()'), '') END as "sig",
    CASE WHEN (array_length(fhirpath(t.resource, 'dispenseRequest.quantity.value')) > 1) OR (array_length(list_filter(fhirpath(t.resource, '(dispenseRequest.quantity.value).type().name'), _t -> NOT (_t IN ('Decimal', 'Integer', 'decimal', 'integer', 'integer64', 'positiveInt', 'unsignedInt')))) > 0) THEN error('ViewDefinition column ''quantity_num'' path ''dispenseRequest.quantity.value'' violates collection=false / declared type decimal') ELSE fhirpath_number(t.resource, 'dispenseRequest.quantity.value') END as "quantity_num",
    CASE WHEN (array_length(fhirpath(t.resource, 'dispenseRequest.expectedSupplyDays')) > 1) OR (array_length(list_filter(fhirpath(t.resource, '(dispenseRequest.expectedSupplyDays).type().name'), _t -> NOT (_t IN ('Integer', 'integer', 'integer64', 'positiveInt', 'unsignedInt')))) > 0) THEN error('ViewDefinition column ''days_supply'' path ''dispenseRequest.expectedSupplyDays'' violates collection=false / declared type integer') ELSE TRY_CAST(fhirpath_number(t.resource, 'dispenseRequest.expectedSupplyDays') AS INTEGER) END as "days_supply",
    CASE WHEN (array_length(fhirpath(t.resource, 'iif(medication.ofType(CodeableConcept).coding.where(system=''http://www.nlm.nih.gov/research/umls/rxnorm'').exists(), medication.ofType(CodeableConcept).coding.where(system=''http://www.nlm.nih.gov/research/umls/rxnorm'').code.first(), medication.ofType(CodeableConcept).coding.code.first())')) > 1) OR ((array_length(fhirpath(t.resource, '(iif(medication.ofType(CodeableConcept).coding.where(system=''http://www.nlm.nih.gov/research/umls/rxnorm'').exists(), medication.ofType(CodeableConcept).coding.where(system=''http://www.nlm.nih.gov/research/umls/rxnorm'').code.first(), medication.ofType(CodeableConcept).coding.code.first())).type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(iif(medication.ofType(CodeableConcept).coding.where(system=''http://www.nlm.nih.gov/research/umls/rxnorm'').exists(), medication.ofType(CodeableConcept).coding.where(system=''http://www.nlm.nih.gov/research/umls/rxnorm'').code.first(), medication.ofType(CodeableConcept).coding.code.first())).type().name'), _t -> NOT (_t IN ('code', 'string')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, 'iif(medication.ofType(CodeableConcept).coding.where(system=''http://www.nlm.nih.gov/research/umls/rxnorm'').exists(), medication.ofType(CodeableConcept).coding.where(system=''http://www.nlm.nih.gov/research/umls/rxnorm'').code.first(), medication.ofType(CodeableConcept).coding.code.first())'), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(iif(medication.ofType(CodeableConcept).coding.where(system=''http://www.nlm.nih.gov/research/umls/rxnorm'').exists(), medication.ofType(CodeableConcept).coding.where(system=''http://www.nlm.nih.gov/research/umls/rxnorm'').code.first(), medication.ofType(CodeableConcept).coding.code.first())).type().name')) = 0)) THEN error('ViewDefinition column ''drug_source_value'' path ''iif(medication.ofType(CodeableConcept).coding.where(system=%rxnorm_uri).exists(), medication.ofType(CodeableConcept).coding.where(system=%rxnorm_uri).code.first(), medication.ofType(CodeableConcept).coding.code.first())'' violates collection=false / declared type code') ELSE NULLIF(fhirpath_text(t.resource, 'iif(medication.ofType(CodeableConcept).coding.where(system=''http://www.nlm.nih.gov/research/umls/rxnorm'').exists(), medication.ofType(CodeableConcept).coding.where(system=''http://www.nlm.nih.gov/research/umls/rxnorm'').code.first(), medication.ofType(CodeableConcept).coding.code.first())'), '') END as "drug_source_value",
    CASE WHEN (array_length(fhirpath(t.resource, 'encounter.reference.split(''/'').last()')) > 1) OR ((array_length(fhirpath(t.resource, '(encounter.reference.split(''/'').last()).type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(encounter.reference.split(''/'').last()).type().name'), _t -> NOT (_t IN ('String', 'base64Binary', 'canonical', 'code', 'id', 'markdown', 'oid', 'string', 'uri', 'url', 'uuid')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, 'encounter.reference.split(''/'').last()'), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(encounter.reference.split(''/'').last()).type().name')) = 0)) THEN error('ViewDefinition column ''visit_occurrence_id'' path "encounter.reference.split(''/'').last()" violates collection=false / declared type string') ELSE NULLIF(fhirpath_text(t.resource, 'encounter.reference.split(''/'').last()'), '') END as "visit_occurrence_id",
    CASE WHEN (array_length(fhirpath(t.resource, '''MedicationRequest''')) > 1) OR ((array_length(fhirpath(t.resource, '(''MedicationRequest'').type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(''MedicationRequest'').type().name'), _t -> NOT (_t IN ('String', 'base64Binary', 'canonical', 'code', 'id', 'markdown', 'oid', 'string', 'uri', 'url', 'uuid')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, '''MedicationRequest'''), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(''MedicationRequest'').type().name')) = 0)) THEN error('ViewDefinition column ''src'' path "''MedicationRequest''" violates collection=false / declared type string') ELSE NULLIF(fhirpath_text(t.resource, '''MedicationRequest'''), '') END as "src"
FROM "__vd_src" t
LEFT JOIN "omop"."omop_conceptmap" "cm" ON
    NULLIF(fhirpath_text(t.resource, 'iif(medication.ofType(CodeableConcept).coding.where(system=''http://www.nlm.nih.gov/research/umls/rxnorm'').exists(), medication.ofType(CodeableConcept).coding.where(system=''http://www.nlm.nih.gov/research/umls/rxnorm'').code.first(), medication.ofType(CodeableConcept).coding.code.first())'), '') =
    NULLIF("cm"."concept_code", '')
  AND NULLIF(fhirpath_text(t.resource, 'iif(medication.ofType(CodeableConcept).coding.where(system=''http://www.nlm.nih.gov/research/umls/rxnorm'').exists(), ''http://www.nlm.nih.gov/research/umls/rxnorm'', medication.ofType(CodeableConcept).coding.system.first())'), '') =
    NULLIF("cm"."source_system", '')
WHERE json_extract_string(t.resource, '$.resourceType') = 'MedicationRequest';
CREATE SCHEMA IF NOT EXISTS omop;
CREATE OR REPLACE VIEW omop."drug_exposure__medication_statement" AS
SELECT
    CASE WHEN (array_length(fhirpath(t.resource, 'id')) > 1) OR (array_length(list_filter(fhirpath(t.resource, '(id).type().name'), _t -> NOT (_t IN ('id', 'string')))) > 0) THEN error('ViewDefinition column ''drug_exposure_id'' path ''id'' violates collection=false / declared type id') ELSE NULLIF(fhirpath_text(t.resource, 'id'), '') END as "drug_exposure_id",
    CASE WHEN (array_length(fhirpath(t.resource, 'subject.reference.split(''/'').last()')) > 1) OR ((array_length(fhirpath(t.resource, '(subject.reference.split(''/'').last()).type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(subject.reference.split(''/'').last()).type().name'), _t -> NOT (_t IN ('String', 'base64Binary', 'canonical', 'code', 'id', 'markdown', 'oid', 'string', 'uri', 'url', 'uuid')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, 'subject.reference.split(''/'').last()'), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(subject.reference.split(''/'').last()).type().name')) = 0)) THEN error('ViewDefinition column ''person_id'' path "subject.reference.split(''/'').last()" violates collection=false / declared type string') ELSE NULLIF(fhirpath_text(t.resource, 'subject.reference.split(''/'').last()'), '') END as "person_id",
