CREATE OR REPLACE VIEW omop."drug_exposure" AS
SELECT CAST(hash(drug_exposure_id) & 9223372036854775807 AS BIGINT) AS drug_exposure_id, CAST(hash(person_id) & 9223372036854775807 AS BIGINT) AS person_id, CAST(COALESCE(TRY_CAST(drug_concept_id AS BIGINT), 0) AS BIGINT) AS drug_concept_id, drug_exposure_start_date, drug_exposure_start_datetime, drug_exposure_end_date, drug_exposure_end_datetime, CAST(COALESCE(TRY_CAST(drug_type_concept_id AS BIGINT), 0) AS BIGINT) AS drug_type_concept_id, sig, quantity_num, days_supply, drug_source_value, CAST(hash(visit_occurrence_id) & 9223372036854775807 AS BIGINT) AS visit_occurrence_id, src FROM (
SELECT * FROM omop."drug_exposure__medication_request"
UNION ALL
SELECT * FROM omop."drug_exposure__medication_statement"
UNION ALL
SELECT * FROM omop."drug_exposure__medication_administration"
UNION ALL
SELECT * FROM omop."drug_exposure__medication_dispense"
UNION ALL
SELECT * FROM omop."drug_exposure__immunization"
);
