stem=''http://hl7.org/fhir/sid/icd-10'').exists(), code.coding.where(system=''http://hl7.org/fhir/sid/icd-10'').code.first(), code.coding.code.first())))'), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(iif(code.coding.where(system=''http://snomed.info/sct'').exists(), code.coding.where(system=''http://snomed.info/sct'').code.first(), iif(code.coding.where(system=''http://hl7.org/fhir/sid/icd-10-cm'').exists(), code.coding.where(system=''http://hl7.org/fhir/sid/icd-10-cm'').code.first(), iif(code.coding.where(system=''http://hl7.org/fhir/sid/icd-10'').exists(), code.coding.where(system=''http://hl7.org/fhir/sid/icd-10'').code.first(), code.coding.code.first())))).type().name')) = 0)) THEN error('ViewDefinition column ''condition_source_value'' path ''iif(code.coding.where(system=%snomed_uri).exists(), code.coding.where(system=%snomed_uri).code.first(), iif(code.coding.where(system=%icd10cm_uri).exists(), code.coding.where(system=%icd10cm_uri).code.first(), iif(code.coding.where(system=%icd10_uri).exists(), code.coding.where(system=%icd10_uri).code.first(), code.coding.code.first())))'' violates collection=false / declared type code') ELSE NULLIF(fhirpath_text(t.resource, 'iif(code.coding.where(system=''http://snomed.info/sct'').exists(), code.coding.where(system=''http://snomed.info/sct'').code.first(), iif(code.coding.where(system=''http://hl7.org/fhir/sid/icd-10-cm'').exists(), code.coding.where(system=''http://hl7.org/fhir/sid/icd-10-cm'').code.first(), iif(code.coding.where(system=''http://hl7.org/fhir/sid/icd-10'').exists(), code.coding.where(system=''http://hl7.org/fhir/sid/icd-10'').code.first(), code.coding.code.first())))'), '') END as "condition_source_value",
