    NULLIF(fhirpath_text(t.resource, 'iif(code.coding.where(system=''http://snomed.info/sct'').exists(), code.coding.where(system=''http://snomed.info/sct'').code.first(), iif(code.coding.where(system=''http://hl7.org/fhir/sid/icd-10-cm'').exists(), code.coding.where(system=''http://hl7.org/fhir/sid/icd-10-cm'').code.first(), iif(code.coding.where(system=''http://hl7.org/fhir/sid/icd-10'').exists(), code.coding.where(system=''http://hl7.org/fhir/sid/icd-10'').code.first(), code.coding.code.first())))'), '') =
    NULLIF("cm"."concept_code", '')
  AND NULLIF(fhirpath_text(t.resource, 'iif(code.coding.where(system=''http://snomed.info/sct'').exists(), ''http://snomed.info/sct'', iif(code.coding.where(system=''http://hl7.org/fhir/sid/icd-10-cm'').exists(), ''http://hl7.org/fhir/sid/icd-10-cm'', iif(code.coding.where(system=''http://hl7.org/fhir/sid/icd-10'').exists(), ''http://hl7.org/fhir/sid/icd-10'', code.coding.system.first())))'), '') =
