  AND NULLIF(fhirpath_text(t.resource, '''http://hl7.org/fhir/administrative-gender'''), '') =
    NULLIF("cm"."source_system", '')
WHERE json_extract_string(t.resource, '$.resourceType') = 'Patient'
);
CREATE OR REPLACE VIEW omop."procedure_occurrence" AS
SELECT CAST(hash(procedure_occurrence_id) & 9223372036854775807 AS BIGINT) AS procedure_occurrence_id, CAST(hash(person_id) & 9223372036854775807 AS BIGINT) AS person_id, CAST(COALESCE(TRY_CAST(procedure_concept_id AS BIGINT), 0) AS BIGINT) AS procedure_concept_id, procedure_date, procedure_datetime, CAST(COALESCE(TRY_CAST(procedure_type_concept_id AS BIGINT), 0) AS BIGINT) AS procedure_type_concept_id, quantity, procedure_source_value, CAST(hash(visit_occurrence_id) & 9223372036854775807 AS BIGINT) AS visit_occurrence_id FROM (
