    "cm"."concept_id" as "procedure_concept_id",
    CASE WHEN (array_length(fhirpath(t.resource, 'performed.ofType(dateTime).substring(0, 10)')) > 1) OR ((array_length(fhirpath(t.resource, '(performed.ofType(dateTime).substring(0, 10)).type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(performed.ofType(dateTime).substring(0, 10)).type().name'), _t -> NOT (_t IN ('Date', 'DateTime', 'String', 'date', 'dateTime', 'string')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, 'performed.ofType(dateTime).substring(0, 10)'), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(performed.ofType(dateTime).substring(0, 10)).type().name')) = 0)) THEN error('ViewDefinition column ''procedure_date'' path ''performed.ofType(dateTime).substring(0, 10)'' violates collection=false / declared type date') ELSE NULLIF(fhirpath_text(t.resource, 'performed.ofType(dateTime).substring(0, 10)'), '') END as "procedure_date",
    CASE WHEN (array_length(fhirpath(t.resource, 'performed.ofType(dateTime)')) > 1) OR ((array_length(fhirpath(t.resource, '(performed.ofType(dateTime)).type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(performed.ofType(dateTime)).type().name'), _t -> NOT (_t IN ('Date', 'DateTime', 'String', 'date', 'dateTime', 'string')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, 'performed.ofType(dateTime)'), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(performed.ofType(dateTime)).type().name')) = 0)) THEN error('ViewDefinition column ''procedure_datetime'' path ''performed.ofType(dateTime)'' violates collection=false / declared type dateTime') ELSE NULLIF(fhirpath_text(t.resource, 'performed.ofType(dateTime)'), '') END as "procedure_datetime",
    CASE WHEN (array_length(fhirpath(t.resource, '''32810''')) > 1) OR ((array_length(fhirpath(t.resource, '(''32810'').type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(''32810'').type().name'), _t -> NOT (_t IN ('String', 'base64Binary', 'canonical', 'code', 'id', 'markdown', 'oid', 'string', 'uri', 'url', 'uuid')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, '''32810'''), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(''32810'').type().name')) = 0)) THEN error('ViewDefinition column ''procedure_type_concept_id'' path ''%ehr_type_concept'' violates collection=false / declared type string') ELSE NULLIF(fhirpath_text(t.resource, '''32810'''), '') END as "procedure_type_concept_id",
    CASE WHEN (array_length(fhirpath(t.resource, '1')) > 1) OR ((array_length(fhirpath(t.resource, '(1).type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(1).type().name'), _t -> NOT (_t IN ('Integer', 'integer', 'integer64', 'positiveInt', 'unsignedInt')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, '1'), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(1).type().name')) = 0)) THEN error('ViewDefinition column ''quantity'' path ''1'' violates collection=false / declared type integer') ELSE TRY_CAST(fhirpath_number(t.resource, '1') AS INTEGER) END as "quantity",
    CASE WHEN (array_length(fhirpath(t.resource, 'iif(code.coding.where(system=''http://snomed.info/sct'').exists(), code.coding.where(system=''http://snomed.info/sct'').code.first(), iif(code.coding.where(system=''http://www.ama-assn.org/go/cpt'').exists(), code.coding.where(system=''http://www.ama-assn.org/go/cpt'').code.first(), code.coding.code.first()))')) > 1) OR ((array_length(fhirpath(t.resource, '(iif(code.coding.where(system=''http://snomed.info/sct'').exists(), code.coding.where(system=''http://snomed.info/sct'').code.first(), iif(code.coding.where(system=''http://www.ama-assn.org/go/cpt'').exists(), code.coding.where(system=''http://www.ama-assn.org/go/cpt'').code.first(), code.coding.code.first()))).type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(iif(code.coding.where(system=''http://snomed.info/sct'').exists(), code.coding.where(system=''http://snomed.info/sct'').code.first(), iif(code.coding.where(system=''http://www.ama-assn.org/go/cpt'').exists(), code.coding.where(system=''http://www.ama-assn.org/go/cpt'').code.first(), code.coding.code.first()))).type().name'), _t -> NOT (_t IN ('code', 'string')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, 'iif(code.coding.where(system=''http://snomed.info/sct'').exists(), code.coding.where(system=''http://snomed.info/sct'').code.first(), iif(code.coding.where(system=''http://www.ama-assn.org/go/cpt'').exists(), code.coding.where(system=''http://www.ama-assn.org/go/cpt'').code.first(), code.coding.code.first()))'), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(iif(code.coding.where(system=''http://snomed.info/sct'').exists(), code.coding.where(system=''http://snomed.info/sct'').code.first(), iif(code.coding.where(system=''http://www.ama-assn.org/go/cpt'').exists(), code.coding.where(system=''http://www.ama-assn.org/go/cpt'').code.first(), code.coding.code.first()))).type().name')) = 0)) THEN error('ViewDefinition column ''procedure_source_value'' path ''iif(code.coding.where(system=%snomed_uri).exists(), code.coding.where(system=%snomed_uri).code.first(), iif(code.coding.where(system=%cpt4_uri).exists(), code.coding.where(system=%cpt4_uri).code.first(), code.coding.code.first()))'' violates collection=false / declared type code') ELSE NULLIF(fhirpath_text(t.resource, 'iif(code.coding.where(system=''http://snomed.info/sct'').exists(), code.coding.where(system=''http://snomed.info/sct'').code.first(), iif(code.coding.where(system=''http://www.ama-assn.org/go/cpt'').exists(), code.coding.where(system=''http://www.ama-assn.org/go/cpt'').code.first(), code.coding.code.first()))'), '') END as "procedure_source_value",
    CASE WHEN (array_length(fhirpath(t.resource, 'encounter.reference.split(''/'').last()')) > 1) OR ((array_length(fhirpath(t.resource, '(encounter.reference.split(''/'').last()).type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(encounter.reference.split(''/'').last()).type().name'), _t -> NOT (_t IN ('String', 'base64Binary', 'canonical', 'code', 'id', 'markdown', 'oid', 'string', 'uri', 'url', 'uuid')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, 'encounter.reference.split(''/'').last()'), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(encounter.reference.split(''/'').last()).type().name')) = 0)) THEN error('ViewDefinition column ''visit_occurrence_id'' path "encounter.reference.split(''/'').last()" violates collection=false / declared type string') ELSE NULLIF(fhirpath_text(t.resource, 'encounter.reference.split(''/'').last()'), '') END as "visit_occurrence_id"
FROM "__vd_src" t
LEFT JOIN "omop"."omop_conceptmap" "cm" ON
    NULLIF(fhirpath_text(t.resource, 'iif(code.coding.where(system=''http://snomed.info/sct'').exists(), code.coding.where(system=''http://snomed.info/sct'').code.first(), iif(code.coding.where(system=''http://www.ama-assn.org/go/cpt'').exists(), code.coding.where(system=''http://www.ama-assn.org/go/cpt'').code.first(), code.coding.code.first()))'), '') =
