CREATE OR REPLACE VIEW omop."visit_occurrence" AS
SELECT CAST(hash(visit_occurrence_id) & 9223372036854775807 AS BIGINT) AS visit_occurrence_id, CAST(hash(person_id) & 9223372036854775807 AS BIGINT) AS person_id, CAST(COALESCE(TRY_CAST(visit_concept_id AS BIGINT), 0) AS BIGINT) AS visit_concept_id, visit_start_date, visit_start_datetime, visit_end_date, visit_end_datetime, CAST(COALESCE(TRY_CAST(visit_type_concept_id AS BIGINT), 0) AS BIGINT) AS visit_type_concept_id, visit_source_value FROM (
