    "cm"."concept_id" as "visit_concept_id",
    CASE WHEN (array_length(fhirpath(t.resource, 'period.start.substring(0, 10)')) > 1) OR ((array_length(fhirpath(t.resource, '(period.start.substring(0, 10)).type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(period.start.substring(0, 10)).type().name'), _t -> NOT (_t IN ('Date', 'DateTime', 'String', 'date', 'dateTime', 'string')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, 'period.start.substring(0, 10)'), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(period.start.substring(0, 10)).type().name')) = 0)) THEN error('ViewDefinition column ''visit_start_date'' path ''period.start.substring(0, 10)'' violates collection=false / declared type date') ELSE NULLIF(fhirpath_text(t.resource, 'period.start.substring(0, 10)'), '') END as "visit_start_date",
    CASE WHEN (array_length(fhirpath(t.resource, 'period.start')) > 1) OR (array_length(list_filter(fhirpath(t.resource, '(period.start).type().name'), _t -> NOT (_t IN ('Date', 'DateTime', 'String', 'date', 'dateTime', 'string')))) > 0) THEN error('ViewDefinition column ''visit_start_datetime'' path ''period.start'' violates collection=false / declared type dateTime') ELSE NULLIF(fhirpath_text(t.resource, 'period.start'), '') END as "visit_start_datetime",
    CASE WHEN (array_length(fhirpath(t.resource, 'period.end.substring(0, 10)')) > 1) OR ((array_length(fhirpath(t.resource, '(period.end.substring(0, 10)).type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(period.end.substring(0, 10)).type().name'), _t -> NOT (_t IN ('Date', 'DateTime', 'String', 'date', 'dateTime', 'string')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, 'period.end.substring(0, 10)'), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(period.end.substring(0, 10)).type().name')) = 0)) THEN error('ViewDefinition column ''visit_end_date'' path ''period.end.substring(0, 10)'' violates collection=false / declared type date') ELSE NULLIF(fhirpath_text(t.resource, 'period.end.substring(0, 10)'), '') END as "visit_end_date",
    CASE WHEN (array_length(fhirpath(t.resource, 'period.end')) > 1) OR (array_length(list_filter(fhirpath(t.resource, '(period.end).type().name'), _t -> NOT (_t IN ('Date', 'DateTime', 'String', 'date', 'dateTime', 'string')))) > 0) THEN error('ViewDefinition column ''visit_end_datetime'' path ''period.end'' violates collection=false / declared type dateTime') ELSE NULLIF(fhirpath_text(t.resource, 'period.end'), '') END as "visit_end_datetime",
    CASE WHEN (array_length(fhirpath(t.resource, '''32810''')) > 1) OR ((array_length(fhirpath(t.resource, '(''32810'').type().name')) > 0 AND array_length(list_filter(fhirpath(t.resource, '(''32810'').type().name'), _t -> NOT (_t IN ('String', 'base64Binary', 'canonical', 'code', 'id', 'markdown', 'oid', 'string', 'uri', 'url', 'uuid')))) > 0) OR (array_length(list_filter(fhirpath(t.resource, '''32810'''), _v -> COALESCE(json_type(TRY_CAST(CAST(_v AS VARCHAR) AS JSON)) IN ('OBJECT', 'ARRAY'), false))) > 0 AND array_length(fhirpath(t.resource, '(''32810'').type().name')) = 0)) THEN error('ViewDefinition column ''visit_type_concept_id'' path ''%ehr_type_concept'' violates collection=false / declared type string') ELSE NULLIF(fhirpath_text(t.resource, '''32810'''), '') END as "visit_type_concept_id",
    CASE WHEN (array_length(fhirpath(t.resource, 'class.code')) > 1) OR (array_length(list_filter(fhirpath(t.resource, '(class.code).type().name'), _t -> NOT (_t IN ('code', 'string')))) > 0) THEN error('ViewDefinition column ''visit_source_value'' path ''class.code'' violates collection=false / declared type code') ELSE NULLIF(fhirpath_text(t.resource, 'class.code'), '') END as "visit_source_value"
FROM "__vd_src" t
LEFT JOIN "omop"."omop_conceptmap" "cm" ON
